const wireText=(call,kind)=>{assert.equal(call.kind,kind);assert.equal(call.status,200);assert.equal(call.terminalReason,'end');assert.equal(call.responseComplete,true);assert.equal(call.responseCaptureTruncated,false);if(Object.prototype.hasOwnProperty.call(call,'error'))assert.equal(call.error,null);assert.equal(call.model,process.env.OLLAMA_MODEL);assert.equal(Buffer.byteLength(call.request),call.requestBytes);assert.equal(Buffer.byteLength(call.response),call.responseBytes);assert.equal(call.responseObservedBytes,call.responseBytes);assert(Number.isSafeInteger(call.responseChunkCount)&&call.responseChunkCount>0);assert.equal(hash(call.request),call.requestSha256);assert.equal(hash(call.response),call.responseSha256);const request=JSON.parse(call.request);assert.equal(request.model,process.env.OLLAMA_MODEL);const rows=call.response.trim().split('\n').map(line=>JSON.parse(line));assert(rows.length>0);assert(rows.every((row,index)=>row.model===process.env.OLLAMA_MODEL&&!Object.prototype.hasOwnProperty.call(row,'error')&&row.message?.role==='assistant'&&typeof row.message.content==='string'&&row.done===(index===rows.length-1)));assert.equal(rows.at(-1).done_reason,'stop');return rows.map(row=>row.message.content).join('');};
